32	            }
33	        }
34	
35	        if let Some(cand) = chunk.candidates.into_iter().next() {
36	            if let Some(content) = cand.content {
37	                for part in content.parts {
38	                    if let Some(text) = part.text {
39	                        out.push(Ok(ModelEvent::TokenDelta { text }));
40	                    } else if let Some(fc) = part.function_call {
41	                        self.saw_function_call = true;
42	                        let call_id = fc.id.unwrap_or_else(|| {
43	                            let id = format!("fc_{}", self.fn_index);
44	                            self.fn_index += 1;
45	                            id
