47	                        out.push(Ok(ModelEvent::ToolCallDelta {
48	                            call_id,
49	                            name: Some(fc.name),
50	                            args_delta: fc.args.to_string(),
51	                        }));
52	                    }
53	                }
54	            }
55	            if let Some(fr) = cand.finish_reason {
56	                self.finish_reason = Some(fr);
57	            }
58	        }
59	
60	        if let Some(u) = chunk.usage_metadata {
61	            out.push(Ok(ModelEvent::Usage {
62	                input_tokens: u.prompt_token_count,
63	                output_tokens: u.candidates_token_count,
