72	    /// Emit the terminal `Finish` — only when a `finishReason` was observed.
73	    pub(crate) fn finish(&mut self) -> Vec<Result<ModelEvent, ModelError>> {
74	        let Some(reason) = self.finish_reason.take() else {
75	            return Vec::new();
76	        };
