441	/// Build the terminal `[Usage, Finish]` event pair from a response's
442	/// usage snapshot, status, and optional `incomplete_details.reason` string.
443	///
444	/// When `incomplete_reason` is `Some`, it overrides the status-based mapping:
445	/// - `"max_output_tokens"` → `Finish { Length }`
446	/// - `"content_filter"` → `Finish { ContentFilter }`
447	/// - other string → `Finish { Other(reason) }`
448	fn terminal_events(
449	    usage: Option<ResponseUsage>,
450	    status: Status,
451	    incomplete_reason: Option<&str>,
452	) -> Vec<ModelEvent> {
453	    let mut out = Vec::new();
454	
455	    if let Some(u) = usage {
456	        out.push(ModelEvent::Usage {
457	            input_tokens: u.input_tokens,
458	            output_tokens: u.output_tokens,
459	            cached_input_tokens: Some(u.input_tokens_details.cached_tokens),
460	            reasoning_tokens: Some(u.output_tokens_details.reasoning_tokens),
461	        });
462	    }
463	
464	    let reason = if let Some(r) = incomplete_reason {
465	        match r {
466	            "max_output_tokens" => FinishReason::Length,
467	            "content_filter" => FinishReason::ContentFilter,
468	            other => FinishReason::Other(other.to_owned()),
469	        }
470	    } else {
471	        match status {
472	            Status::Completed => FinishReason::Stop,
473	            Status::Failed => FinishReason::Other("failed".to_owned()),
474	            Status::Incomplete => FinishReason::Length,
475	            Status::Cancelled => FinishReason::Other("cancelled".to_owned()),
476	            Status::Queued => FinishReason::Other("queued".to_owned()),
477	            Status::InProgress => FinishReason::Other("in_progress".to_owned()),
478	        }
479	    };
480	
481	    out.push(ModelEvent::Finish { reason });
482	    out
483	}
